Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

$Root = (Get-Location).Path
$ExpectedBranch = "feature/vitrine-marketplace"
$BackupRoot = Join-Path $Root (".orcaly-cupons-backup-" + (Get-Date -Format "yyyyMMddHHmmss"))
$PatchFile = Join-Path $env:TEMP ("orcaly-cupons-patch-" + [Guid]::NewGuid().ToString("N") + ".js")
$Utf8 = New-Object System.Text.UTF8Encoding($false)

$ExistingFiles = @(
  "app\painel\cupons\page.tsx",
  "app\api\public-site\[slug]\route.ts",
  "components\public-site\PublicSiteRenderer.tsx",
  "components\public-site\SegmentMarketplaceCatalog.tsx",
  "components\public-site\FoodMarketplaceCatalog.tsx"
)

$NewFiles = @(
  "components\public-site\PublicCouponsBand.tsx"
)

$TouchedFiles = @(
  $ExistingFiles + $NewFiles
)

function Write-Base64File {
  param(
    [Parameter(Mandatory = $true)][string]$Path,
    [Parameter(Mandatory = $true)][string]$Base64
  )

  $Bytes = [Convert]::FromBase64String(($Base64 -replace "\s", ""))
  $Content = [Text.Encoding]::UTF8.GetString($Bytes)
  New-Item -ItemType Directory -Force -Path (Split-Path $Path -Parent) | Out-Null
  [IO.File]::WriteAllText($Path, $Content.TrimEnd() + "`n", $Utf8)
}

function Restore-OrcalyBackup {
  Write-Host ""
  Write-Host "Restaurando arquivos anteriores..." -ForegroundColor Yellow

  foreach ($Relative in $ExistingFiles) {
    $Source = Join-Path $BackupRoot $Relative
    $Destination = Join-Path $Root $Relative

    if (Test-Path -LiteralPath $Source) {
      New-Item -ItemType Directory -Force -Path (Split-Path $Destination -Parent) | Out-Null
      Copy-Item -LiteralPath $Source -Destination $Destination -Force
    }
  }

  foreach ($Relative in $NewFiles) {
    $Backup = Join-Path $BackupRoot $Relative
    $Destination = Join-Path $Root $Relative

    if (Test-Path -LiteralPath $Backup) {
      New-Item -ItemType Directory -Force -Path (Split-Path $Destination -Parent) | Out-Null
      Copy-Item -LiteralPath $Backup -Destination $Destination -Force
    }
    elseif (Test-Path -LiteralPath $Destination) {
      Remove-Item -LiteralPath $Destination -Force
    }
  }
}

if (-not (Test-Path -LiteralPath (Join-Path $Root "package.json"))) {
  throw "Execute este script na raiz do projeto Orçaly."
}

$Branch = (& git branch --show-current | Out-String).Trim()
if ($Branch -ne $ExpectedBranch) {
  throw "Branch atual: $Branch. Use $ExpectedBranch."
}

foreach ($Relative in $ExistingFiles) {
  $Path = Join-Path $Root $Relative
  if (-not (Test-Path -LiteralPath $Path)) {
    throw "Arquivo obrigatório não encontrado: $Relative"
  }
}

New-Item -ItemType Directory -Force -Path $BackupRoot | Out-Null

foreach ($Relative in $ExistingFiles) {
  $Source = Join-Path $Root $Relative
  $Destination = Join-Path $BackupRoot $Relative
  New-Item -ItemType Directory -Force -Path (Split-Path $Destination -Parent) | Out-Null
  Copy-Item -LiteralPath $Source -Destination $Destination -Force
}

foreach ($Relative in $NewFiles) {
  $Source = Join-Path $Root $Relative

  if (Test-Path -LiteralPath $Source) {
    $Destination = Join-Path $BackupRoot $Relative
    New-Item -ItemType Directory -Force -Path (Split-Path $Destination -Parent) | Out-Null
    Copy-Item -LiteralPath $Source -Destination $Destination -Force
  }
}

try {
  Write-Host "==> Repaginando cupons e integrando à vitrine - R2" -ForegroundColor Cyan

  Write-Base64File `
    -Path (Join-Path $Root "app\painel\cupons\page.tsx") `
    -Base64 @'

'@

  Write-Base64File `
    -Path (Join-Path $Root "components\public-site\PublicCouponsBand.tsx") `
    -Base64 @'

'@

  Write-Base64File `
    -Path $PatchFile `
    -Base64 @'

'@

  Push-Location $Root
  try {
    & node $PatchFile
    $PatchExitCode = $LASTEXITCODE
  }
  finally {
    Pop-Location
  }

  Write-Host "PATCH_NODE_EXIT_CODE=$PatchExitCode" -ForegroundColor Yellow

  if ($PatchExitCode -ne 0) {
    throw "O patch Node falhou."
  }

  $Checks = @(
    @("app\painel\cupons\page.tsx", "ORCALY_COUPON_CENTER_V2"),
    @("components\public-site\PublicCouponsBand.tsx", "ORCALY_PUBLIC_COUPONS_BAND_V2"),
    @("app\api\public-site\[slug]\route.ts", "ORCALY_PUBLIC_COUPONS_API_V2"),
    @("components\public-site\PublicSiteRenderer.tsx", "ORCALY_PUBLIC_COUPONS_RENDERER_V2"),
    @("components\public-site\SegmentMarketplaceCatalog.tsx", "ORCALY_PUBLIC_COUPON_PREFILL_V2"),
    @("components\public-site\FoodMarketplaceCatalog.tsx", "ORCALY_PUBLIC_COUPON_PREFILL_V2"),
    @("app\api\public-site\[slug]\route.ts", "marketplace_coupons: publicCoupons"),
    @("components\public-site\PublicSiteRenderer.tsx", "PublicCouponsBand"),
    @("components\public-site\SegmentMarketplaceCatalog.tsx", "couponStorageKey"),
    @("components\public-site\FoodMarketplaceCatalog.tsx", "couponStorageKey")
  )

  Write-Host ""
  Write-Host "==> Verificando marcadores" -ForegroundColor Cyan

  foreach ($Check in $Checks) {
    $Relative = $Check[0]
    $Pattern = $Check[1]
    $Path = Join-Path $Root $Relative

    $Match = Select-String `
      -LiteralPath $Path `
      -Pattern $Pattern `
      -SimpleMatch `
      -ErrorAction SilentlyContinue

    if (-not $Match) {
      throw "Verificação falhou: $Relative -> $Pattern"
    }

    Write-Host "[OK] $Relative -> $Pattern" -ForegroundColor Green
  }

  Write-Host ""
  Write-Host "==> Verificando diff" -ForegroundColor Cyan
  & git diff --check -- @($TouchedFiles)

  if ($LASTEXITCODE -ne 0) {
    throw "git diff --check encontrou problemas."
  }

  if (Test-Path -LiteralPath (Join-Path $Root ".next")) {
    Remove-Item -LiteralPath (Join-Path $Root ".next") -Recurse -Force
  }

  Write-Host ""
  Write-Host "==> Executando build completo" -ForegroundColor Cyan
  & npm run build
  $BuildExitCode = $LASTEXITCODE

  Write-Host ""
  Write-Host "BUILD_EXIT_CODE=$BuildExitCode" -ForegroundColor Yellow

  if ($BuildExitCode -ne 0) {
    throw "O build falhou."
  }

  Remove-Item -LiteralPath $BackupRoot -Recurse -Force

  Write-Host ""
  Write-Host "==================================================" -ForegroundColor Magenta
  Write-Host "CUPONS REPAGINADOS E INTEGRADOS AO SITE - R2" -ForegroundColor Magenta
  Write-Host "==================================================" -ForegroundColor Magenta
  Write-Host "Painel: /painel/cupons"
  Write-Host "Site: cupons válidos aparecem após a capa"
  Write-Host "Checkout: código selecionado fica pré-preenchido"
  Write-Host "Segmentos: Food, Loja, Gráfica, Serviços e demais vitrines"
  Write-Host ""
  Write-Host "Nenhum commit, push ou deploy foi criado."
}
catch {
  Restore-OrcalyBackup
  throw
}
finally {
  if (Test-Path -LiteralPath $PatchFile) {
    Remove-Item -LiteralPath $PatchFile -Force
  }
}
